export type TrackListener = (tracks: readonly string[]) => void;
export type Unsubscribe = () => void;

export class PlaylistStore {
  private tracks: string[];
  private readonly listeners = new Set<TrackListener>();

  public constructor(initial: readonly string[] = ['First track', 'Second track']) {
    PlaylistStore.assertTracks(initial);
    this.tracks = initial.slice();
  }

  public snapshot(): readonly string[] {
    return this.tracks;
  }

  public replace(next: readonly string[]): void {
    PlaylistStore.assertTracks(next);
    this.tracks = next.slice();
    const pending = Array.from(this.listeners);
    for (const listener of pending) {
      listener(this.snapshot());
    }
  }

  public subscribe(listener: TrackListener): Unsubscribe {
    if (typeof listener !== 'function') {
      throw new TypeError('Listener must be a function');
    }
    this.listeners.add(listener);
    listener(this.snapshot());
    let active = true;
    return (): void => {
      if (active) {
        active = false;
        this.listeners.delete(listener);
      }
    };
  }

  private static assertTracks(tracks: readonly string[]): void {
    if (!Array.isArray(tracks) || tracks.some((track) => typeof track !== 'string' || track.trim().length === 0)) {
      throw new TypeError('Tracks must be non-empty strings');
    }
  }
}

