import { PlaylistStore } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function arrayEqual(actual: readonly unknown[], expected: readonly unknown[], message: string): void {
  equal(actual.length, expected.length, `${message} length`);
  for (let i = 0; i < expected.length; i += 1) equal(actual[i], expected[i], `${message}[${i}]`);
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const defaults = new PlaylistStore();
arrayEqual(defaults.snapshot(), ['First track', 'Second track'], 'default playlist');

const source = ['  intro  ', 'repeat', 'repeat'];
const store = new PlaylistStore(source);
source[0] = 'changed';
arrayEqual(store.snapshot(), ['  intro  ', 'repeat', 'repeat'], 'constructor copies and preserves values');

const firstSnapshot = store.snapshot() as string[];
const secondSnapshot = store.snapshot();
assert(firstSnapshot !== secondSnapshot, 'snapshots must be fresh arrays');
firstSnapshot[0] = 'mutated snapshot';
arrayEqual(store.snapshot(), ['  intro  ', 'repeat', 'repeat'], 'snapshot mutation must not affect state');

const replacement = ['one', 'two'];
store.replace(replacement);
replacement[0] = 'outside mutation';
arrayEqual(store.snapshot(), ['one', 'two'], 'replace copies its input');

throwsTypeError(() => store.replace(['valid', '   ']), 'blank track must be rejected');
arrayEqual(store.snapshot(), ['one', 'two'], 'failed replacement must preserve state');
throwsTypeError(() => new PlaylistStore(['ok', 3 as unknown as string]), 'non-string track must be rejected');

const events: string[] = [];
let active = false;
let unsubscribeSecond: () => void = () => undefined;
let unsubscribeLate: (() => void) | undefined;
const unsubscribeFirst = store.subscribe((tracks) => {
  if (!active) return;
  events.push(`first:${tracks.join(',')}`);
  (tracks as string[])[0] = 'listener mutation';
  unsubscribeSecond();
  unsubscribeLate = store.subscribe((lateTracks) => events.push(`late:${lateTracks.join(',')}`));
});
unsubscribeSecond = store.subscribe((tracks) => {
  if (active) events.push(`second:${tracks.join(',')}`);
});
active = true;
store.replace(['next']);
arrayEqual(events, ['first:next', 'late:next', 'second:next'], 'replace listener snapshot and subscription semantics');
arrayEqual(store.snapshot(), ['next'], 'listener mutation must not affect state');
unsubscribeSecond();
unsubscribeSecond();
unsubscribeFirst();
unsubscribeLate?.();

let stoppedListenerRan = false;
let throwNow = false;
const stopError = new Error('stop');
const unsubscribeThrower = store.subscribe(() => { if (throwNow) throw stopError; });
const unsubscribeStopped = store.subscribe(() => { if (throwNow) stoppedListenerRan = true; });
throwNow = true;
let propagated: unknown;
try { store.replace([]); } catch (error) { propagated = error; }
equal(propagated, stopError, 'listener exception identity must propagate');
equal(stoppedListenerRan, false, 'listener exception must stop the notification pass');
arrayEqual(store.snapshot(), [], 'replacement state remains isolated and supports empty playlists');
unsubscribeThrower();
unsubscribeStopped();

